#include "algorithms/scheduler.h"
#include <QDateTime>
namespace oas {void Scheduler::setPlan(QString n,std::vector<SessionTarget>t){targets_=std::move(t);status_.name=std::move(n);status_.targetCount=int(targets_.size());status_.targetIndex=0;status_.completedFrames=0;status_.state="ready";emit statusChanged(status_);}std::optional<SessionTarget> Scheduler::currentTarget()const{if(status_.targetIndex<0||status_.targetIndex>=int(targets_.size()))return{};return targets_[status_.targetIndex];}bool Scheduler::start(){if(targets_.empty())return false;status_.id="session-"+QDateTime::currentDateTimeUtc().toString("yyyyMMddTHHmmss");status_.active=true;status_.state="running";emit statusChanged(status_);return true;}void Scheduler::stop(){status_.active=false;status_.state="stopped";emit statusChanged(status_);}void Scheduler::markFrameCompleted(){++status_.completedFrames;emit statusChanged(status_);}void Scheduler::advanceTarget(){if(status_.targetIndex+1<status_.targetCount)++status_.targetIndex;else{status_.active=false;status_.state="completed";}emit statusChanged(status_);}}
